script:
(function () {
  'use strict';
  // 401(k) contribution effects on your paycheck (tax year 2026). A traditional 401(k) deferral of
  // pct% of pay comes out before federal income tax and the flat state rate, but Social Security and
  // Medicare still apply, so take-home falls by less than the amount you save:
  //   take-home drop = deferral - federal tax saved - state tax saved.
  // Employer match = match% x your deferral, on pay up to cap% of salary (pay counted up to the
  // 401(a)(17) limit). Deferrals are capped at the 402(g) limit plus any catch-up for your age.
  // Checked in Node (fake DOM, whole script): $60,000 single biweekly, 4% state: at 3% federal tax $4,804
  // (1,240 + 12% x 29,700) = $184.77/check; at 6% $4,588 = $176.46/check; SS $143.08; the 3% -> 6% change saves
  // $216 federal + $72 state = $288 a year and cuts take-home by $58.15/check while adding $103.85 (incl. a
  // 50%-up-to-6% match of $69.23). $400,000 at 10%, age 50: deferral capped at $32,500 and the match figured
  // on the $360,000 pay limit (6% x 50% = $10,800). Payroll core matches take-home-paycheck-calculator
  // (single $75,000, 5%, $100/check: federal $6,273.00, SS $4,488.80, Medicare $1,049.80).
  // ---- 2026 FEDERAL PAYROLL CONSTANTS (tax year 2026) ----------------------------------
  // Copied from take-home-paycheck-calculator (verified there). Brackets and standard
  // deductions: IRS Rev. Proc. 2025-32 (as amended by P.L. 119-21). Child tax credit $2,200 and
  // $500 other-dependent credit: IRC 24(h) as amended by P.L. 119-21. Social Security wage base
  // and rate: SSA 2026 fact sheet. Medicare and 0.9% Additional Medicare: IRC 3101(b).
  var TAX_YEAR = 2026;
  var BRACKETS = { // upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj:    [24800, 100800, 211400, 403550, 512450, 768700],
    mfs:    [12400, 50400, 105700, 201775, 256225, 384350],
    hoh:    [17700, 67450, 105700, 201750, 256200, 640600]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var STANDARD_DEDUCTION = { single: 16100, mfj: 32200, mfs: 16100, hoh: 24150 };
  var CHILD_CREDIT = 2200, OTHER_DEPENDENT_CREDIT = 500;
  var CREDIT_PHASEOUT_START = { single: 200000, hoh: 200000, mfs: 200000, mfj: 400000 }; // $50 per $1,000
  var SS_RATE = 0.062, SS_WAGE_BASE = 184500;
  var MEDICARE_RATE = 0.0145, ADDL_MEDICARE_RATE = 0.009, ADDL_MEDICARE_WITHHOLD_START = 200000;
  // ---------------------------------------------------------------------------------------

  function bracketTax(taxable, limits) {
    var tax = 0, lower = 0, marginal = 0;
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] : Infinity;
      if (taxable > lower) { tax += (Math.min(taxable, upper) - lower) * RATES[i]; marginal = RATES[i]; }
      lower = upper;
    }
    return { tax: tax, marginal: marginal };
  }

  // Annual paycheck model. o: gross, status, pretaxDefer (traditional plan deferral: exempt from
  // federal and flat state tax, still FICA wages), rothDefer (after-tax plan deferral), sec125
  // (health premiums etc.: exempt from federal, state and FICA), post (other after-tax deductions),
  // stateRate (%), kids, otherDeps, extraWH (extra federal withholding). All $ amounts are annual.
  function payroll(o) {
    var gross = o.gross, defer = o.pretaxDefer || 0, roth = o.rothDefer || 0;
    var sec125 = Math.min(o.sec125 || 0, Math.max(0, gross - defer));
    var ficaWages = Math.max(0, gross - sec125);
    var fedWages = Math.max(0, gross - defer - sec125);
    var taxable = Math.max(0, fedWages - STANDARD_DEDUCTION[o.status]);
    var bt = bracketTax(taxable, BRACKETS[o.status]);
    var credits = (o.kids || 0) * CHILD_CREDIT + (o.otherDeps || 0) * OTHER_DEPENDENT_CREDIT;
    credits = Math.max(0, credits - Math.ceil(Math.max(0, fedWages - CREDIT_PHASEOUT_START[o.status]) / 1000) * 50);
    var federal = Math.max(0, bt.tax - credits) + (o.extraWH || 0);
    var ss = SS_RATE * Math.min(ficaWages, SS_WAGE_BASE);
    var medicare = MEDICARE_RATE * ficaWages + ADDL_MEDICARE_RATE * Math.max(0, ficaWages - ADDL_MEDICARE_WITHHOLD_START);
    var state = (o.stateRate || 0) / 100 * fedWages;
    var post = o.post || 0;
    var net = gross - defer - roth - sec125 - federal - ss - medicare - state - post;
    return { gross: gross, defer: defer, roth: roth, sec125: sec125, ficaWages: ficaWages, fedWages: fedWages,
             taxable: taxable, federal: federal, marginal: bt.marginal, ss: ss, medicare: medicare, state: state,
             post: post, net: net, taxes: federal + ss + medicare + state };
  }
  // ---- 2026 401(k) LIMITS (IRS Notice 2025-67, tax year 2026) ----------------------------------
  var LIMITS = {
    deferral: 24500,        // 402(g) elective deferral limit
    catchUp50: 8000,        // catch-up, age 50 or older
    catchUp60to63: 11250,   // SECURE 2.0 catch-up for ages 60-63 (replaces the age-50 amount)
    compensation: 360000    // 401(a)(17) pay that can be counted for the match
  };
  // ---------------------------------------------------------------------------------------
  function limitFor(band) { return LIMITS.deferral + (band === '60' ? LIMITS.catchUp60to63 : band === '50' ? LIMITS.catchUp50 : 0); }

  // o: salary, status, stateRate, band, match, cap (decimals), sec125, post, kids, otherDeps (annual $)
  function scenario(o, pct) {
    var wanted = o.salary * pct / 100;
    var room = Math.max(0, o.salary - o.sec125 - o.post);
    var defer = Math.min(wanted, limitFor(o.band), room);
    var effPct = o.salary > 0 ? defer / o.salary : 0;
    var match = Math.min(o.salary, LIMITS.compensation) * o.match * Math.min(effPct, o.cap);
    var r = payroll({ gross: o.salary, status: o.status, pretaxDefer: defer, sec125: o.sec125, post: o.post,
                      stateRate: o.stateRate, kids: o.kids, otherDeps: o.otherDeps });
    r.match = match; r.capped = wanted > defer + 0.005; r.total = defer + match;
    return r;
  }
  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2, minimumFractionDigits: 2 });
  var wholeFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function money(x) { return moneyFmt.format(Math.abs(x) < 0.005 ? 0 : x); }
  function whole(x) { return wholeFmt.format(Math.abs(x) < 0.5 ? 0 : x); }
  function signed(x) { if (Math.abs(x) < 0.005) return money(0); return (x < 0 ? '−' : '+') + moneyFmt.format(Math.abs(x)); }
  function minus(x) { return Math.abs(x) < 0.005 ? money(0) : '−' + moneyFmt.format(Math.abs(x)); }
  function pctText(x) { return (Math.round(x * 10) / 10) + '%'; }
  function num(id) { var el = document.getElementById(id); if (!el) return NaN; var v = parseFloat(el.value); return isNaN(v) ? NaN : v; }
  function val(id) { var el = document.getElementById(id); return el ? el.value : ''; }
  function setText(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }
  // rows: arrays of cells; a cell is a string or {t: text, strong: bool}. The first cell is a row header.
  // A row given as {group: text, span: n} becomes a full-width group heading.
  function fillTable(id, rows) {
    var body = document.getElementById(id);
    if (!body) return;
    while (body.firstChild) body.removeChild(body.firstChild);
    rows.forEach(function (row) {
      var tr = document.createElement('tr');
      if (row.group) {
        var g = document.createElement('th');
        g.setAttribute('scope', 'colgroup'); g.colSpan = row.span; g.textContent = row.group;
        tr.appendChild(g); body.appendChild(tr); return;
      }
      row.forEach(function (c, i) {
        var el = document.createElement(i === 0 ? 'th' : 'td');
        if (i === 0) el.setAttribute('scope', 'row');
        var text = typeof c === 'object' ? c.t : c;
        if (typeof c === 'object' && c.strong) { var s = document.createElement('strong'); s.textContent = text; el.appendChild(s); }
        else el.textContent = text;
        tr.appendChild(el);
      });
      body.appendChild(tr);
    });
  }
  function showError(id, msg) { var e = document.getElementById(id); if (!e) return; e.hidden = !msg; e.textContent = msg || ''; }
  function showNote(id, notes) { var n = document.getElementById(id); if (!n) return; n.hidden = notes.length === 0; n.textContent = notes.join(' '); }
  function wire(formId, update) {
    document.addEventListener('DOMContentLoaded', function () {
      var form = document.getElementById(formId);
      if (!form) return;
      var run = function () { try { update(); } catch (err) { /* keep the page usable */ } };
      form.addEventListener('input', run);
      form.addEventListener('change', run);
      form.addEventListener('submit', function (e) { e.preventDefault(); });
      run();
    });
  }
  function update() {
    var o = {
      salary: num('keSalary'), status: val('keStatus'), stateRate: num('keState'), band: val('keAge'),
      match: num('keMatch') / 100, cap: num('keMatchCap') / 100, kids: Math.round(num('keKids')),
      otherDeps: Math.round(num('keOtherDeps'))
    };
    var p = parseInt(val('keFreq'), 10), cur = num('keCurrent'), nw = num('keNew');
    var pre = num('kePretax'), post = num('kePost');
    if (!BRACKETS[o.status]) o.status = 'single';
    if (!(p > 0)) p = 26;
    var all = [o.salary, o.stateRate, o.match, o.cap, o.kids, o.otherDeps, cur, nw, pre, post];
    if (all.some(function (v) { return !isFinite(v) || v < 0; }) || o.salary > 1e8 || cur > 100 || nw > 100 ||
        o.stateRate > 20 || o.match > 2 || o.cap > 1 || o.kids > 20 || o.otherDeps > 20) {
      showError('keError', 'Enter a salary, contribution rates from 0 to 100%, a match up to 200%, a state rate from 0 to 20% and non-negative amounts.');
      return;
    }
    o.sec125 = pre * p; o.post = post * p;
    if (o.sec125 + o.post > o.salary) { showError('keError', 'Your other deductions add up to more than your pay.'); return; }
    showError('keError', '');

    var a = scenario(o, cur), b = scenario(o, nw);
    var dNet = (b.net - a.net) / p, dSaved = (b.total - a.total) / p, dDefer = b.defer - a.defer;
    setText('keNetChange', signed(dNet));
    setText('keSavedChange', signed(dSaved));
    setText('keCostPerDollar', Math.abs(dDefer) > 0.005 ? money(-(b.net - a.net) / dDefer) : '–');
    setText('keNetCur', money(a.net / p));
    setText('keNetNew', money(b.net / p));
    setText('keTaxSaved', whole((a.federal + a.state) - (b.federal + b.state)));
    setText('keMatchNew', money(b.match / p));
    var missed = Math.min(o.salary, LIMITS.compensation) * o.match * o.cap - b.match;
    setText('keMissed', whole(Math.max(0, missed)));
    setText('keLimit', whole(limitFor(o.band)));

    fillTable('keCompare', [
      ['Gross pay', money(a.gross / p), money(b.gross / p), signed(0)],
      ['Your 401(k) contribution', minus(a.defer / p), minus(b.defer / p), signed(-(b.defer - a.defer) / p)],
      ['Federal income tax', minus(a.federal / p), minus(b.federal / p), signed(-(b.federal - a.federal) / p)],
      ['Social Security', minus(a.ss / p), minus(b.ss / p), signed(-(b.ss - a.ss) / p)],
      ['Medicare', minus(a.medicare / p), minus(b.medicare / p), signed(-(b.medicare - a.medicare) / p)],
      ['State and local income tax', minus(a.state / p), minus(b.state / p), signed(-(b.state - a.state) / p)],
      ['Other deductions', minus((a.sec125 + a.post) / p), minus((b.sec125 + b.post) / p), signed(0)],
      [{ t: 'Take-home pay', strong: true }, { t: money(a.net / p), strong: true }, { t: money(b.net / p), strong: true }, { t: signed(dNet), strong: true }],
      ['Employer match', money(a.match / p), money(b.match / p), signed((b.match - a.match) / p)],
      [{ t: 'Total into your 401(k)', strong: true }, { t: money(a.total / p), strong: true }, { t: money(b.total / p), strong: true }, { t: signed(dSaved), strong: true }]
    ]);

    var base = scenario(o, 0), rows = [];
    for (var k = 0; k <= 15; k++) {
      var s = scenario(o, k), tag = [];
      if (Math.abs(k - cur) < 1e-9) tag.push('current');
      if (Math.abs(k - nw) < 1e-9) tag.push('new');
      if (s.capped) tag.push('at limit');
      var label = k + '%' + (tag.length ? ' (' + tag.join(', ') + ')' : '');
      rows.push([tag.length && !s.capped ? { t: label, strong: true } : label, money(s.defer / p), money(s.match / p),
                 money(s.net / p), minus((base.net - s.net) / p), money(s.total / p), whole(s.total)]);
    }
    fillTable('keSteps', rows);

    var notes = [];
    if (b.capped || a.capped) notes.push('Contributions are capped at your ' + TAX_YEAR + ' limit of ' + whole(limitFor(o.band)) + '.');
    if (missed > 0.5) notes.push('At ' + pctText(nw) + ' you leave ' + whole(missed) + ' a year of employer match unclaimed. Contributing ' + pctText(o.cap * 100) + ' of pay captures all of it.');
    if (o.salary > LIMITS.compensation && o.match > 0) notes.push('The match is figured on pay up to the ' + whole(LIMITS.compensation) + ' compensation limit.');
    showNote('keNote', notes);
  }

  wire('keForm', update);
})();
